import polars as pl

class _PolarsDataFrameCompat(pl.DataFrame):
    """Thin wrapper to support .to_dict(orient='records') on a Polars DataFrame."""
    def to_dict(self, orient: str = 'records'):
        if orient != 'records':
            raise ValueError("Only orient='records' is supported")
        return self.to_dicts()


def summarize_sales(filepath: str) -> _PolarsDataFrameCompat:
    df = pl.read_csv(filepath, try_parse_dates=True)

    # Extract year-month string matching pandas Period('M') format, e.g. '2023-04'
    df = df.with_columns(
        pl.col('date').dt.strftime('%Y-%m').alias('month')
    )

    summary = (
        df.group_by(['region', 'month'])
        .agg([
            pl.col('revenue').sum().alias('total_revenue'),
            pl.col('revenue').mean().alias('avg_order_value'),
            pl.col('order_id').count().alias('num_orders'),
        ])
        .sort(['region', 'month'])
    )

    return _PolarsDataFrameCompat._from_dict(summary.to_dict(as_series=False))

